      ('competition',t('竞品分析','Competitive analysis'),t('有人守着品牌的声音<br>有人守着发布的日历','One tool keeps the voice<br>another keeps the calendar')),
      ('research',t('用户研究','User research'),t('去两门真实的生意里<br>看内容怎么发出去','Two real businesses<br>one publishing problem')),
      ('insights',t('洞察与机会','Insights & opportunities'),t('每个人都在重复介绍自己<br>也都不敢直接点发布','Everyone re-explained their brand<br>no one wanted to post blind')),
      ('architecture',t('信息架构与原型','Architecture & prototyping'),t('六件散活<br>收成三步','Six scattered chores<br>three connected steps')),
      ('interface',t('界面与设计系统','UI & design system'),t('把视线<br>留给草稿','Keep the eye<br>on the draft')),
