    html+=f'<div class="design-system"><div><p class="eyebrow">{t("视觉语言","Visual language")}</p><h3>{t("低饱和环境光<br>与清楚的阅读表面","Light and dark<br>with the same hierarchy")}</h3><p>{t("减少强边框与重复强调，用留白、字级和少量灰绿区分任务优先级。","Less border weight and fewer competing accents. Space, type, and a restrained green distinguish priorities.")}</p><div class="swatches" aria-label="{t("雾白、浅灰绿、石墨、灰绿配色","Mist, pale sage, graphite, and muted green palette")}"><span class="swatch" style="background:#f0f3f2"></span><span class="swatch" style="background:#dce5df"></span><span class="swatch" style="background:#202629"></span><span class="swatch" style="background:#89bcb1"></span></div><div class="type-specimen"><strong>{t("字 01","Aa 01")}</strong><span>{t("正文优先<br>数字清晰，层级克制","Reading first<br>Clear numbers, quiet hierarchy")}</span></div></div><div><div class="theme-tabs" role="tablist" aria-label="{t("主题预览","Theme preview")}"><button id="theme-light" role="tab" aria-selected="true" aria-controls="theme-panel-light">{t("雾白","Mist")}</button><button id="theme-dark" role="tab" aria-selected="false" aria-controls="theme-panel-dark" tabindex="-1">{t("石墨","Graphite")}</button></div><div class="theme-preview" role="tabpanel" id="theme-panel-light" aria-labelledby="theme-light">{image('agent-'+short+'-light',t("智能体 · 雾白主题","Agent · mist theme"))}</div><div class="theme-preview" role="tabpanel" id="theme-panel-dark" aria-labelledby="theme-dark" hidden>{image('agent-'+short+'-dark',t("智能体 · 石墨主题","Agent · graphite theme"))}</div></div></div>'+end
    html+=start(8)+head(8,t('AI 起草这件事已经不难，难的是分清哪些可以放手，哪一步必须让人拿主意。这一章是几次具体的取舍，也包括我亲手删掉的两样东西。','Getting AI to draft is no longer the hard part. The hard part is deciding what to hand over and which step must stay with a person. This chapter is a handful of those calls, including two things I deleted myself.'))
    html+=f'<article class="memory-study" id="brand-context"><div class="case-subhead"><span class="eyebrow">01 / {t("上下文设计","Context design")}</span><h3>{t("把品牌变成可编辑的上下文","Make brand context visible and editable")}</h3><p>{t("早期版本把品牌检查放在最后。十一份草稿全部生成完，系统才提醒语气可能不一致。提醒没错，就是来得太晚，用户已经改了半天，只能整段重来。后来我把规则挪到生成之前，品牌名怎么写、哪些数字不能改、哪些词不许出现，先进上下文，生成完再查一遍。","Early on, the brand check ran last. All eleven drafts were generated before the system warned that the tone might be off. The warning was right, it just came too late: people had already edited, and starting over felt like punishment. So I moved the rules before generation. How the brand is spelled, which numbers can’t change, which words are off-limits all go into context first, then get checked again afterwards.")}</p></div><div class="memory-evidence">{image("memory-"+short+"-light",t("品牌记忆 · 实际保存的个人与品牌资料","Brand memory · saved personal and brand context"))}</div><div class="memory-reasoning"><div><span class="eyebrow">{t("已保存的表达原则","Saved voice principle")}</span><blockquote>{t("清楚、可信、不过度承诺","Clear, credible, without overpromising")}</blockquote><span class="memory-owner">{t("赵越","Joey Zhao")} · {t("个人 + 品牌","Person + brand")}</span></div><div><h4>{t("我的设计判断","The design decision")}</h4><p>{t("反复要讲的背景单独存起来，每次的素材留在工作台。品牌资料一放就是几个月，素材每次都换，两样东西就该放在两个地方，用户也能看见 AI 写作时到底参考了什么。","Context you repeat goes into memory; each task’s source stays on the workbench. Brand information lasts for months while sources change every time, so they live in separate places, and people can always see what the AI was working from.")}</p></div></div></article>'
    html+=f'<article class="channel-study" id="channels"><div class="case-subhead"><span class="eyebrow">02 / {t("平台适配","Channel adaptation")}</span><h3>{t("同一份素材，写出不同的开场","One source, two different openings")}</h3><p>{t("从已保存的内容包中，取出 X 与 LinkedIn 的两份草稿，以下为中文译文。","Two drafts from the same saved content kit, for X and LinkedIn.")}</p></div><div class="source-brief"><span class="eyebrow">{t("原始素材节选","Source excerpt")}</span><p>{t("Finfold 帮助独立创始人与小团队，把一次产品更新转成适合不同平台的内容草稿。","Finfold helps solo founders and small teams turn one product update into platform-specific content drafts.")}</p><div class="source-tags"><span>{t("一次产品更新","One product update")}</span><span>{t("两个平台","Two channels")}</span><span>{t("发布前审核","Review before publishing")}</span></div></div><div class="channel-branches" aria-hidden="true"><span>↙</span><span>↘</span></div><div class="channel-comparison"><article class="channel-draft"><div class="draft-top"><span class="channel-mark">𝕏</span><strong>X / Twitter</strong><span class="draft-label">{t("草稿译文","Draft excerpt")}</span></div><blockquote>{t("独立创始人并不讨厌写作。他们讨厌的是，把同一条更新换四种方式再写一遍。","Solo founders don’t hate writing. They hate writing the same update four different ways.")}</blockquote><div class="draft-structure"><span>01</span><p>{t("直接抛出重复劳动的痛点","Open directly with the repeated work")}</p><span>02</span><p>{t("用编号串起工作流与限制","Number the workflow and its limits")}</p></div><div class="draft-conclusion">{t("短句开场 · 分段推进","Short hook · Numbered thread")}</div></article><article class="channel-draft"><div class="draft-top"><span class="channel-mark linkedin-mark">in</span><strong>LinkedIn</strong><span class="draft-label">{t("草稿译文","Draft excerpt")}</span></div><blockquote>{t("很多独立创始人只在一个平台发布，其他平台就慢慢放下了。<br><br>倒也谈不上懒，时间就这么多，分不过来。","Most solo founders publish one platform and quietly abandon the rest.<br><br>Not from laziness. From arithmetic.")}</blockquote><div class="draft-structure"><span>01</span><p>{t("从创始人的处境建立共鸣","Start with the founder’s situation")}</p><span>02</span><p>{t("展开工作方式与设计取舍","Explain the workflow and design choices")}</p></div><div class="draft-conclusion">{t("情境开场 · 叙事展开","Situational hook · Narrative structure")}</div></article></div><p class="channel-takeaway">{t("平台切换改变表达结构，事实与审核入口始终保留","The structure changes by channel; the facts and review controls stay in view")}</p></article>'
    html+=f'<article class="channel-study" id="honest-states"><div class="case-subhead"><span class="eyebrow">03 / {t("诚实的状态","Honest states")}</span><h3>{t("我删掉了两样<br>让演示更好看的东西","I deleted two things<br>that made the demo look better")}</h3><p>{t("这两处改动在截图里几乎看不出来，演示效果甚至变差了。我还是删了，因为用户的账号经营了很久，一段带错事实的文案发出去，损失落在他们身上。","Neither change shows up in a screenshot, and the demo got slightly worse. I made them anyway. People spend years building an account, and one post with a wrong fact lands on them, not on us.")}</p></div><div class="decision-list">'+''.join(f'<div class="decision-row"><span>0{i+1}</span><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate([(t('一组漂亮的假数字','A row of pretty fake numbers'),t('第一版总览页写着 42 条待发布、11 条待审核、18 条已排期，产品看上去很成熟。数字来自演示数据，我把整组都删了，宁可让新用户先看到空的状态。','The first overview screen showed 42 posts queued, 11 in review, 18 scheduled. It made the product look mature. The numbers were demo data, so the whole row went. An honest empty state is better than a borrowed full one.')),(t('一份永远成功的兜底','A fallback that always succeeded'),t('模型报错时，系统会悄悄塞进一份模板，卡片照样显示成功。演示很顺，可用户分不清哪份是模型写的，哪份只是模板。现在失败的卡片会写明原因，可以单独重试，已经成功的结果原样保留。','When the model failed, the system quietly slipped in a template and still showed success. Demos ran smoothly, and users had no way to tell which drafts the model wrote and which were filler. Now a failed card says why, can be retried on its own, and every successful result stays put.'))]))+'</div></article>'
    details=[('agent-detail-'+short,t('先让人知道从哪里开始','Make the starting point obvious'),t('智能体首屏保留输入与常用任务。工作面板按需打开，避免第一次进入就面对全部能力。','The Agent opens with a prompt and common tasks. Supporting panels appear when needed, so the first screen stays approachable.')),('review-detail-'+short,t('常用操作留在结果旁边','Keep frequent actions next to the result'),t('编辑与复制直接可达。高级选项收进次级区域，让注意力回到需要检查的内容。','Editing and copying stay within reach. Secondary controls step back so the content remains the focus.'))]
